write./etc/apt/apt.conf.d/99ios3ds-speed:
// Cydia refresh on a 400 MHz ARM11.
// Do not spend minutes on a hanging host, retry or fetch translations.
Acquire::http::Timeout "10";
Acquire::https::Timeout "10";
Acquire::Retries "0";
Acquire::Languages "none";
// Most sources publish Packages as gz, bz2 and lzma; gzip decompresses
// much faster on the ARM11 (measured: emu/cydia_perf.py --fill 2000 --bz2).
Acquire::CompressionTypes::Order { "gz"; "bz2"; "lzma"; };
